// Jobindsats tabel-liste — én pr. ydelsestype
const TOKEN = 'NW0vH4Cx-WCn_rtxgHfEPlm2pTop-xRK8PiBiH5uSIs';
const BASE  = 'https://api.jobindsats.dk/v3/data';
const OMRADE = '/40/';  // Hvidovre
const PERIODE = 'latest:24';

const tabeller = [
  { id: 'y01a02', navn: 'A-dagpenge',          ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y60a02', navn: 'Kontanthjælp',         ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y07a02', navn: 'Sygedagpenge',         ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y11a02', navn: 'Ressourceforløb',      ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y09a02', navn: 'Ledighedsydelse',      ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y08a02', navn: 'Fleksjob',             ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y12a02', navn: 'Jobafklaringsforløb',  ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y10a02', navn: 'Førtidspension',       ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y85a02', navn: 'Tidlig pension',       ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y13a02', navn: 'Seniorpension',        ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y40a02', navn: 'Barselsdagpenge',      ftpKol: 'Antal fuldtidspersoner' },
  { id: 'y28a02', navn: 'Efterløn',             ftpKol: 'Antal fuldtidspersoner med udbetalt efterløn' },
];

return tabeller.map(t => ({
  json: {
    tableId: t.id,
    navn:    t.navn,
    ftpKol:  t.ftpKol,
    url:     `${BASE}/${t.id}?mgroup.*=*&period.M=${PERIODE}&hierarchy._nykom=${OMRADE}&format=json`,
    token:   TOKEN
  }
}));

// Hent alle HTTP-svar + original tabelmeta fra node 1
const httpSvar   = $input.all();
const tabelmeta  = $('1. Byg tabelliste').all();

const MDR = {'01':'Jan','02':'Feb','03':'Mar','04':'Apr','05':'Maj',
             '06':'Jun','07':'Jul','08':'Aug','09':'Sep','10':'Okt',
             '11':'Nov','12':'Dec'};

function formatPeriode(p) {
  const year = p.slice(2,4);
  const mNum = p.slice(6,8) || p.slice(5,7);
  return (MDR[mNum] || mNum) + ' ' + year;
}
function diff(a, b) { return (a != null && b != null) ? a - b : null; }
function pct(a, b)  { return (a != null && b != null && b !== 0) ? Math.round((a-b)/b*10)/10 : null; }

const dataUdtraek = {};
const promptData  = {};
let senesteLabel  = '—';

for (let i = 0; i < httpSvar.length; i++) {
  const meta = tabelmeta[i]?.json || {};
  const resp = httpSvar[i]?.json  || {};
  const { tableId, navn, ftpKol } = meta;

  if (!resp.columns || !resp.rows || resp.code) {
    dataUdtraek[tableId] = { navn, labels: [], ftp: [], forrigeLabels: [], forrigeFtp: [], fejl: true };
    promptData[tableId]  = { navn, fejl: true };
    continue;
  }

  const cols   = resp.columns;
  const ftpIdx = cols.indexOf(ftpKol);
  const perIdx = cols.indexOf('Periode');

  if (ftpIdx < 0) {
    dataUdtraek[tableId] = { navn, labels: [], ftp: [], forrigeLabels: [], forrigeFtp: [], fejl: true };
    promptData[tableId]  = { navn, fejl: true, note: 'Kolonne ikke fundet: ' + ftpKol };
    continue;
  }

  // Sorter kronologisk og split i to 12-måneders perioder
  const alle = [...resp.rows].sort((a,b) => a[perIdx].localeCompare(b[perIdx]));
  const har24 = alle.length >= 24;

  const aktuelRows  = alle.slice(-12);                      // Seneste 12 mdr
  const forrigeRows = har24 ? alle.slice(-24, -12) : [];   // Forudgående 12 mdr

  const labels       = aktuelRows.map(r => formatPeriode(r[perIdx]));
  const ftp          = aktuelRows.map(r => r[ftpIdx] != null ? Number(r[ftpIdx]) : null);
  const forrigeLabels = forrigeRows.map(r => formatPeriode(r[perIdx]));
  const forrigeFtp    = forrigeRows.map(r => r[ftpIdx] != null ? Number(r[ftpIdx]) : null);

  const n     = ftp.length;
  const sidst   = ftp[n-1];
  const forrige = ftp[n-2];
  const toMdr   = ftp[n-3];
  const foerste = ftp.find(v => v != null);
  const forrigeAarSidst = forrigeFtp[forrigeFtp.length-1];

  if (labels[n-1]) senesteLabel = labels[n-1];

  dataUdtraek[tableId] = { navn, labels, ftp, forrigeLabels, forrigeFtp };

  promptData[tableId] = {
    navn,
    senesteManed:         labels[n-1] || '—',
    sidst, forrige, toManederSiden: toMdr,
    aendringVsForrige:    diff(sidst, forrige),
    aendringVsForrigePct: pct(sidst, forrige),
    aendringVsToMdr:      diff(sidst, toMdr),
    aendringVsAarSiden:   diff(sidst, forrigeAarSidst),
    aendringVsAarPct:     pct(sidst, forrigeAarSidst),
    udvikling12Mdr:       aktuelRows.map((r, idx) => ({ label: labels[idx], ftp: ftp[idx] })),
    forrigeAar12Mdr:      forrigeRows.map((r, idx) => ({ label: forrigeLabels[idx], ftp: forrigeFtp[idx] })),
  };
}


// Komprimeret opsummering til AI — kun hvad der er nødvendigt
const aiKontekst = {};
for (const [id, d] of Object.entries(promptData)) {
  if (d.fejl) { aiKontekst[id] = { navn: d.navn, fejl: true }; continue; }
  aiKontekst[id] = {
    navn:          d.navn,
    senesteManed:  d.senesteManed,
    sidst:         d.sidst,
    forrige:       d.forrige,
    toManederSiden: d.toManederSiden,
    diffMdr:       d.aendringVsForrige,
    diffMdrPct:    d.aendringVsForrigePct,
    diffAar:       d.aendringVsAarSiden,
    diffAarPct:    d.aendringVsAarPct,
  };
}

return [{ json: {
  dataUdtraek,
  promptData,
  aiKontekst,
  senesteLabel,
  genereretDato: new Date().toISOString().slice(0,10)
}}];

const aiRaw = $input.first().json.output || '';
let analyse = { overskrift: 'Analyse ikke tilgængelig', tekst: 'Kør n8n-flowet for at generere en analyse.' };
try {
  analyse = JSON.parse(aiRaw.replace(/```json|```/g, '').trim());
} catch(e) {
  analyse.tekst = 'AI-analysen kunne ikke parses: ' + e.message;
}

const b = $('3. Saml og beregn data').first().json;

const output = {
  genereret:    b.genereretDato,
  senesteLabel: b.senesteLabel,
  data:         b.dataUdtraek,
  analyse:      analyse
};

return [{ json: {
  fileContent:   JSON.stringify(output, null, 2),
  genereretDato: b.genereretDato,
  senesteLabel:  b.senesteLabel
}}];

const githubSvar = $input.first().json;
const sha = githubSvar?.sha || '';
const d   = $('5. Byg JSON-indhold').first().json;
return [{ json: { sha, fileContent: d.fileContent, senesteLabel: d.senesteLabel, genereretDato: d.genereretDato } }];

